#!/usr/bin/env python3
"""Generate offline reading views. Build-only deps: mistune, beautifulsoup4.
No network calls or third-party browser dependencies in generated HTML.
"""
from pathlib import Path
import json
import html
import re
import mistune
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[1]
H=html.escape
cards=[json.loads(l) for l in (ROOT/'cards/cards.jsonl').read_text().splitlines()]
family_names={c['family']:c['family_name'] for c in cards}
css=r'''
:root{--nav:#142736;--ink:#172c3a;--muted:#61747f;--accent:#11746d;--line:#dce5e9;--soft:#f0f5f7;--bg:#eef3f5;--white:#fff;--bad:#a23f37;--badbg:#fff6f4;--good:#216957;--goodbg:#f1f9f5;--bound:#83621a;--boundbg:#fffaf0}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.8 -apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif}a{color:var(--accent);text-underline-offset:3px}a:hover{text-decoration:none}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #d7a33e;outline-offset:3px}h1,h2,h3{line-height:1.4;letter-spacing:-.025em}h1{font-size:38px;margin:0 0 18px}h2{font-size:25px;margin:45px 0 20px}h3{font-size:19px;margin:29px 0 14px}p{margin:13px 0}code{font:13px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;background:#ecf2f5;padding:2px 5px;border-radius:4px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#142d3b;color:#e1edf2;border-radius:9px;padding:22px;line-height:1.6;font-size:13px;overflow:auto}pre code{padding:0;background:none;color:inherit}blockquote{border-left:3px solid var(--accent);padding:10px 20px;margin:22px 0;background:#f1f7f7}blockquote p{margin:7px 0}.kicker{font-size:12px;letter-spacing:.13em;font-weight:750;color:var(--accent);margin-bottom:15px}.muted{color:var(--muted)}.small{font-size:13px}.badge{display:inline-block;font-size:11px;letter-spacing:.03em;border:1px solid var(--line);border-radius:5px;padding:3px 8px;background:#f9fbfc;color:var(--muted);vertical-align:middle}.badge.warn{border-color:#d8bd7b;background:#fff9eb;color:#7c5f22}.table-scroll{overflow-x:auto;margin:22px 0;border:1px solid var(--line);border-radius:8px}table{border-collapse:collapse;width:100%;font-size:13px;min-width:610px}th,td{padding:12px 14px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{background:#edf5f5;font-weight:700}tr:last-child td{border:0}tr:nth-child(even) td{background:#fbfcfd}ul,ol{padding-left:24px}li{margin:7px 0}.notice{padding:15px 19px;border:1px solid #d2e1e5;border-radius:8px;background:#f4f8fa;font-size:14px}.navlink{font-size:13px;display:inline-block;margin-right:18px}.doc-sidebar{position:fixed;inset:0 auto 0 0;width:260px;background:var(--nav);color:#dceaf0;overflow-y:auto;padding:31px 20px}.doc-sidebar .brand{font-size:23px;font-weight:750;color:#fff}.doc-sidebar .sub{font-size:12px;color:#a8c0cd;margin:7px 0 23px}.doc-sidebar a{display:block;text-decoration:none;color:#c8dbe4;font-size:12px;line-height:1.55;padding:7px 9px;margin:2px 0;border-radius:5px}.doc-sidebar a:hover{background:#284352;color:#fff}.doc-sidebar .toplinks{border-top:1px solid #36505c;border-bottom:1px solid #36505c;padding:10px 0;margin:15px 0}.document{max-width:1080px;margin:28px 30px 60px 290px;background:#fff;padding:46px 58px;border:1px solid var(--line);border-radius:12px}.document h2{border-top:1px solid var(--line);padding-top:28px}.document h1+ p{color:var(--muted)}.document a{overflow-wrap:anywhere}.app-shell{max-width:1240px;margin:auto;padding:36px 30px 60px}.app-header{display:flex;align-items:flex-start;justify-content:space-between;gap:25px}.header-aside{text-align:right;flex-shrink:0;padding-top:7px}.header-aside a{display:block;font-size:13px;margin-bottom:8px}.stat-row{display:flex;gap:10px;margin:26px 0}.stat{flex:1;background:var(--white);border:1px solid var(--line);border-radius:8px;padding:17px 20px}.stat strong{display:block;font-size:26px;font-weight:750;line-height:1.4}.stat span{font-size:12px;color:var(--muted)}.controls{background:var(--white);border:1px solid var(--line);border-radius:10px;padding:20px;margin:23px 0}.filter-row{display:grid;grid-template-columns:minmax(250px,2fr) 1fr 1fr;gap:14px}.controls label{display:block;font-size:12px;color:var(--muted);margin:0 0 6px}.controls input,.controls select{height:44px;border:1px solid #c9d8df;border-radius:6px;padding:8px 11px;background:#fff;color:var(--ink);width:100%;min-width:0;font-size:14px}.controls input::placeholder{color:#879aa5}.chips{display:flex;gap:7px;flex-wrap:wrap;margin-top:16px}.chip{border:1px solid var(--line);border-radius:6px;padding:6px 11px;background:#f8fafb;font-size:12px;color:#476170}.chip.active{background:var(--accent);border-color:var(--accent);color:white}.results-bar{display:flex;justify-content:space-between;align-items:center;margin:20px 1px 13px;font-size:13px;color:var(--muted)}.results-bar button{background:none;border:0;color:var(--accent);font-size:13px;padding:4px 7px}.card{background:#fff;border:1px solid var(--line);border-radius:10px;margin:0 0 12px;scroll-margin-top:22px}.card>summary{list-style:none;cursor:pointer;padding:19px 23px;display:flex;align-items:flex-start;gap:17px}.card>summary::-webkit-details-marker{display:none}.card>summary::before{content:'+';font:22px/1.4 ui-monospace,monospace;color:var(--accent);flex-shrink:0;margin-top:2px}.card[open]>summary::before{content:'−'}.summary-main{min-width:0;flex:1}.card-id{font:11px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;color:var(--muted)}.card-title{font-size:18px;font-weight:720;line-height:1.5;margin:4px 0}.card-desc{font-size:13px;color:var(--muted);line-height:1.65}.summary-meta{display:flex;gap:6px;align-items:center;flex-wrap:wrap;max-width:190px;justify-content:flex-end}.sev-blocker{color:#963c38;background:#fff2ef;border-color:#f0d3cd}.sev-major{color:#88641e;background:#fff9ed;border-color:#e6d9b9}.sev-minor{color:#46647b;background:#eff5f8;border-color:#d8e3e9}.card-body{padding:0 25px 23px 61px}.context{background:#f4f7f9;border:1px solid #e2e9ed;border-radius:7px;padding:15px 17px;margin-bottom:17px;font-size:14px}.eyebrow{font-size:11px;letter-spacing:.07em;font-weight:750;color:var(--muted);margin-bottom:7px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:14px}.example{border-radius:7px;padding:17px 18px;border:1px solid}.example.bad{background:var(--badbg);border-color:#eed6d0}.example.good{background:var(--goodbg);border-color:#d1e6da}.bad .eyebrow{color:var(--bad)}.good .eyebrow{color:var(--good)}.sample{font-size:16px;line-height:1.9;margin:0 0 13px;white-space:pre-wrap}.reason{font-size:13px;line-height:1.75;margin:0;padding-top:12px;border-top:1px solid #0000000d}.boundary{margin:15px 0;background:var(--boundbg);border:1px solid #eadfc2;border-radius:7px;padding:16px 18px}.boundary .eyebrow{color:var(--bound)}.boundary .sample{margin:10px 0;font-size:15px}.boundary-context{font-size:13px;color:#776a4d}.metadata{font-size:12px;color:var(--muted);padding-top:9px;display:flex;gap:8px 17px;flex-wrap:wrap}.metadata a{font:12px/1.8 ui-monospace,monospace}.empty{padding:50px;text-align:center;border:1px dashed #bccdd6;border-radius:8px;color:var(--muted)}.footer{margin-top:35px;font-size:12px;color:var(--muted);border-top:1px solid var(--line);padding-top:19px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(min-width:1500px){.document{margin-left:320px}}@media(max-width:1000px){.doc-sidebar{width:210px;padding:25px 12px}.document{margin:20px 18px 45px 228px;padding:35px 28px}h1{font-size:31px}.summary-meta{max-width:130px}}@media(max-width:720px){.doc-sidebar{position:relative;width:auto;padding:22px}.doc-sidebar nav{max-height:210px;overflow-y:auto}.doc-sidebar .toplinks{display:flex;gap:15px}.document{margin:12px 10px 30px;padding:27px 20px}.document h1{font-size:27px}.app-shell{padding:25px 14px 35px}.app-header{display:block}.header-aside{text-align:left;display:flex;gap:16px;margin:8px 0}.header-aside a{font-size:12px}.stat-row{gap:7px;margin:20px 0}.stat{padding:12px}.stat strong{font-size:23px}.stat span{font-size:11px}.filter-row{grid-template-columns:1fr 1fr}.filter-row>div:first-child{grid-column:1/-1}.controls{padding:16px}.chip{padding:5px 8px;font-size:11px}.card>summary{padding:16px 14px;gap:10px}.card-title{font-size:16px}.summary-meta{max-width:85px;gap:4px}.badge{font-size:10px;padding:2px 5px}.card-body{padding:0 14px 18px}.pair{grid-template-columns:1fr}.sample{font-size:15px}.results-bar{align-items:flex-start}.results-bar>div{white-space:nowrap}h1{font-size:29px}pre{padding:15px}}
@media print{body{background:white;font-size:10.5pt}.doc-sidebar,.header-aside,.controls,.results-bar button{display:none}.document{margin:0;padding:0;max-width:none;border:0}.app-shell{padding:0}.stat-row{display:none}h1{font-size:25pt}h2{font-size:18pt;break-after:avoid}h3{font-size:13pt;break-after:avoid}.card,.example,.boundary{break-inside:avoid}pre{background:#f1f3f5;color:black}.table-scroll{overflow:visible}table{min-width:0;font-size:9pt}thead{display:table-header-group}.card>summary::before{display:none}.card-body{padding:0 18px 18px}a{color:inherit}}
'''

def head(title):
    return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>'+H(title)+'</title><style>'+css+'</style></head>'

# The design is self-contained and includes the walkthrough and implementation handoff.
md=mistune.create_markdown(plugins=['table'])
parts=[]
for name in ('01_design.md','02_walkthrough.md','03_agent_handoff.md'):
    parts.append(md((ROOT/'docs'/name).read_text()))
soup=BeautifulSoup('\n'.join(parts),'html.parser')
for i,h in enumerate(soup.find_all(['h1','h2','h3']),1): h['id']=f'section-{i}'
nav=''.join(f'<a href="#{h["id"]}">{H(h.get_text())}</a>' for h in soup.find_all(['h1','h2']))
for t in soup.find_all('table'):
    wrapper=soup.new_tag('div',attrs={'class':'table-scroll','tabindex':'0'});t.wrap(wrapper)
# Per-source project excerpts are not reproduced; source links remain ordinary references.
page=head('Pi CoC × Jev · 完整设计')+f'''<body><aside class="doc-sidebar"><div class="brand">Pi CoC × Jev</div><div class="sub">表达计划 · 正反例诊断 · 有限修复<br>设计 v1.0 / 2026.09.23</div><div class="toplinks"><a href="card_browser.html">查看 144 张卡片 →</a><a href="README.md">文件包说明</a></div><nav aria-label="设计目录">{nav}</nav></aside><main class="document"><div class="kicker">ENGINEERING DESIGN / EXPRESSION SYSTEM</div><p class="small"><span class="badge">144 张卡</span> <span class="badge">432 段示例</span> <span class="badge warn">种子资产 · 尚未实测 Jev 效果</span></p>{str(soup)}<div class="footer">本页可离线阅读。完整正文由 docs/01_design.md、02_walkthrough.md、03_agent_handoff.md 生成；原始卡库、Schema 与工具均在同一文件包中。</div></main></body></html>'''
(ROOT/'design.html').write_text(page)

# Browser content is embedded; no fetch, CDN, model call, tracking, or API key UI.
data=json.dumps(cards,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
family_opts=''.join(f'<button class="chip" data-family="{f}" aria-pressed="false">{f} · {H(n)}</button>' for f,n in family_names.items())
script=r'''
const cards=JSON.parse(document.getElementById('card-data').textContent);
const labels={blocker:'完整性阻断',major:'主要问题',minor:'表达改善'};
const scopes={turn:'当前回合',clause:'局部句子',dialogue:'对话',window:'跨轮窗口'};
const modes={integrity:'完整性',style:'表达策略',diagnostic_meta:'诊断策略'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let family='ALL';
const target=document.getElementById('cards');
const q=document.getElementById('q'),sev=document.getElementById('severity'),channel=document.getElementById('channel');
const searchable=new Map(cards.map(c=>[c.card_id,JSON.stringify(c).toLowerCase()]));
function oneCard(c){
 const a=c.contrast,b=c.boundary;
 const related=c.related_card_ids.map(id=>`<a href="#${esc(id)}">${esc(id)}</a>`).join(' · ')||'无固定关联';
 return `<details class="card" id="${esc(c.card_id)}"><summary><div class="summary-main"><div class="card-id">${esc(c.card_id)} · INDEX ${c.numeric_id}</div><div class="card-title">${esc(c.title)}</div><div class="card-desc">${esc(c.applicability)}</div></div><div class="summary-meta"><span class="badge sev-${esc(c.default_severity)}">${labels[c.default_severity]}</span><span class="badge">${scopes[c.scope]}</span></div></summary><div class="card-body"><div class="context"><div class="eyebrow">共同上下文 · 正反两段使用相同事实</div>${esc(a.context.authoritative_context)}</div><div class="pair"><section class="example bad"><div class="eyebrow">反例 / VIOLATION</div><p class="sample">${esc(a.negative.text)}</p><p class="reason"><strong>问题：</strong>${esc(c.failure_mode)}</p></section><section class="example good"><div class="eyebrow">正例 / CLEAN</div><p class="sample">${esc(a.positive.text)}</p><p class="reason"><strong>方法：</strong>${esc(c.desired_behavior)}</p></section></div><section class="boundary"><div class="eyebrow">防误判边界例 / ${esc(b.expected_decision)}</div><div class="boundary-context">变更后的上下文：${esc(b.context.authoritative_context)}</div><p class="sample">${esc(b.text)}</p><p class="reason">${esc(b.explanation)}</p></section><div class="metadata"><span>家族：${esc(c.family_name)}</span><span>用途：${modes[c.activation]}</span><span>处理拥有者：<code>${esc(c.repair.owner)}</code></span><span>正例引用：<code>${esc(a.positive.example_id)}</code></span></div><div class="metadata"><span>关联：${related}</span><span>状态：人工复核待完成 / 自动修复未启用</span></div></div></details>`;
}
function render(){
 const query=q.value.trim().toLowerCase();
 const view=cards.filter(c=>(family==='ALL'||c.family===family)&&(!sev.value||c.default_severity===sev.value)&&(!channel.value||c.activation===channel.value)&&(!query||searchable.get(c.card_id).includes(query)));
 target.innerHTML=view.length?view.map(oneCard).join(''):'<div class="empty">没有符合当前条件的卡片。清除搜索或切换家族后重试。</div>';
 document.getElementById('result-count').textContent=`显示 ${view.length} / 144 张卡`;
 document.querySelectorAll('[data-family]').forEach(el=>{const active=el.dataset.family===family;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});
}
function openHash(){
 let id;try{id=decodeURIComponent(location.hash.slice(1));}catch{return;}
 if(!cards.some(c=>c.card_id===id))return;
 family='ALL';q.value='';sev.value='';channel.value='';render();
 const el=document.getElementById(id);el.open=true;el.scrollIntoView({block:'start'});
}
q.addEventListener('input',render);sev.addEventListener('change',render);channel.addEventListener('change',render);
document.querySelectorAll('[data-family]').forEach(el=>el.addEventListener('click',()=>{family=el.dataset.family;render();}));
document.getElementById('expand').addEventListener('click',()=>document.querySelectorAll('.card').forEach(el=>el.open=true));
document.getElementById('collapse').addEventListener('click',()=>document.querySelectorAll('.card').forEach(el=>el.open=false));
document.getElementById('reset').addEventListener('click',()=>{q.value='';sev.value='';channel.value='';family='ALL';render();});
window.addEventListener('hashchange',openHash);
render();if(location.hash)openHash();
'''
page=head('Pi CoC × Jev · 144 张正反例卡片')+f'''<body><main class="app-shell"><header class="app-header"><div><div class="kicker">PI COC × JEV / CARD LIBRARY V1</div><h1>表达正反例卡库</h1><p class="muted">判断具体失误，选择修复方法；让事实不变，让表达有变化。</p></div><div class="header-aside"><a href="design.html">完整设计与接入方案 →</a><a href="cards/cards.md">卡库 Markdown</a><a href="cards/cards.jsonl">机器可读 JSONL</a></div></header><section class="stat-row" aria-label="资产数量"><div class="stat"><strong>144</strong><span>结构化表达卡片</span></div><div class="stat"><strong>12</strong><span>家族 · 每类 12 张</span></div><div class="stat"><strong>432</strong><span>正例、反例与边界文本</span></div></section><div class="notice"><strong>使用边界：</strong>全部为原创教学种子，人工复核与 Jev 效果校准尚未完成。正例只迁移表达方法，不迁移人物、线索和事件。合法边界例只针对当前卡片；它不是在所有场景下都合格的万能句。OUT-008～012 是工程诊断卡，不供旁白模仿。</div><section class="controls" aria-label="卡片筛选"><div class="filter-row"><div><label for="q">搜索卡号、标题、技法或示例内容</label><input id="q" type="search" placeholder="例如：PEC-HOR-001、留白、被动句、玩家授权" autocomplete="off"></div><div><label for="severity">默认问题级别</label><select id="severity"><option value="">全部级别</option><option value="blocker">完整性阻断</option><option value="major">主要问题</option><option value="minor">表达改善</option></select></div><div><label for="channel">卡片用途</label><select id="channel"><option value="">全部用途</option><option value="integrity">完整性</option><option value="style">表达策略</option><option value="diagnostic_meta">诊断策略</option></select></div></div><div class="chips" aria-label="按家族筛选"><button class="chip active" data-family="ALL" aria-pressed="true">全部家族</button>{family_opts}</div></section><div class="results-bar"><span id="result-count" aria-live="polite"></span><div><button id="expand">展开全部</button><button id="collapse">收起</button><button id="reset">重置筛选</button></div></div><section id="cards" aria-label="卡片列表"></section><noscript><p>此浏览器需要 JavaScript 进行本地筛选；无需网络。可直接阅读 <a href="cards/cards.md">Markdown 卡库</a>。</p></noscript><footer class="footer">离线浏览 · 无模型调用 · 无外部脚本 / 字体 / 追踪。此页从 cards/cards.jsonl 生成；库很大不等于每轮全部注入。构建日期：2026-09-23。</footer></main><script id="card-data" type="application/json">{data}</script><script>{script}</script></body></html>'''
(ROOT/'card_browser.html').write_text(page)
print('Built design.html and card_browser.html from source assets.')
